/bin/bash -lc "python - <<'PY'
import io, re, tarfile, requests
j=requests.get('https://pypi.org/pypi/phykit/2.7.0/json',timeout=30).json()
u=next(x['url'] for x in j['urls'] if x['packagetype']=='sdist')
b=requests.get(u,timeout=30).content
with tarfile.open(fileobj=io.BytesIO(b),mode='r:gz') as t:
    for m in t.getmembers():
        if m.name.endswith('.py'):
            s=t.extractfile(m).read().decode('utf-8','replace')
            if 'parsimony_informative_sites' in s or 'ParsimonyInformativeSites' in s:
                print('FILE',m.name)
                for i,line in enumerate(s.splitlines(),1):
                    if re.search(r'parsimony|\\bpis\\b',line,re.I):
                        print(f'{i}: {line}')
PY"
